// Title: How to replace relative hyperlinks with absolute URLs in HTML generated by Aspose.Cells (C#)
// AI Prompts: Generate C# code that creates an Excel workbook with Aspose.Cells, saves it as HTML, and uses a regular expression to convert every href that lacks a scheme into an absolute URL based on a supplied base domain. | Write a C# method that takes the HTML string returned by Workbook.Save(..., SaveFormat.Html) and rewrites all relative hyperlink references to full URLs using string replacement. | Provide a C# example that post‑processes the HTML output from Aspose.Cells to also convert relative image src attributes to absolute URLs after the workbook is saved.
// Common Searches: Aspose.Cells C# convert relative href to absolute URL after saving as HTML | regex replace hyperlink URLs in Aspose.Cells generated HTML .NET | post‑process HTML from Excel workbook to prepend domain to links using C# | how to make hyperlinks in Aspose.Cells HTML export point to full URLs
// Tags: Aspose.Cells HTML hyperlink post‑processing | C# regex replace relative href | convert relative links to absolute URLs .NET | Excel to HTML export hyperlink transformation | base URL prepend for generated HTML

using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using Aspose.Cells;

// The program builds an Excel workbook with Aspose.Cells, inserts a relative hyperlink, saves the workbook as HTML to a memory stream, reads the HTML into a string, applies a case‑insensitive regex to locate href attributes that do not start with http/https, prepends a configurable base URL to make them absolute, and writes the modified HTML to a file.
class Program
{
    static void Main()
    {
        // Base URL to prepend to relative hyperlinks
        const string baseUrl = "https://example.com";

        // ------------------- Create Workbook -------------------
        var workbook = new Workbook();
        var sheet = workbook.Worksheets[0];
        sheet.Name = "Data";

        // Add some sample data
        sheet.Cells["A1"].PutValue("Name");
        sheet.Cells["B1"].PutValue("Website");
        sheet.Cells["A2"].PutValue("Aspose");
        // Insert a relative hyperlink in B2
        sheet.Hyperlinks.Add(1, 1, 1, 1, "/products/cells/net");

        // ------------------- Save as HTML to MemoryStream -------------------
        using (var htmlStream = new MemoryStream())
        {
            workbook.Save(htmlStream, SaveFormat.Html);
            htmlStream.Position = 0;

            // Read the generated HTML into a string
            string htmlContent;
            using (var reader = new StreamReader(htmlStream, Encoding.UTF8))
            {
                htmlContent = reader.ReadToEnd();
            }

            // ------------------- Replace relative URLs with absolute URLs -------------------
            // This regex finds href attributes whose value does NOT start with http:// or https://
            string pattern = @"href\s*=\s*""(?<url>(?!https?:\/\/)[^""]*)""";
            string replacedHtml = Regex.Replace(htmlContent, pattern, m =>
            {
                string relativeUrl = m.Groups["url"].Value;
                // Ensure the relative URL starts with a slash
                if (!relativeUrl.StartsWith("/"))
                    relativeUrl = "/" + relativeUrl;
                string absoluteUrl = $"{baseUrl}{relativeUrl}";
                return $"href=\"{absoluteUrl}\"";
            }, RegexOptions.IgnoreCase);

            // ------------------- Save the final HTML to a file -------------------
            const string outputPath = "Result.html";
            File.WriteAllText(outputPath, replacedHtml, Encoding.UTF8);
            Console.WriteLine($"HTML with absolute hyperlinks saved to: {outputPath}");
        }
    }
}
